import './App.css';
import { useEffect, useState } from 'react'

import { auth, app, db } from './firebase.js';
import { signInWithPopup, GoogleAuthProvider, onAuthStateChanged, signOut } from 'firebase/auth';
import { doc, collection, setDoc, getDoc, addDoc, updateDoc, arrayUnion } from 'firebase/firestore';

import { useAuthState } from 'react-firebase-hooks/auth';


function App() {
  const [user] = useAuthState(auth);
  const [addedPuzzleFlag, setAddedPuzzleFlag] = useState(0);

  return (
    <div className="App">
        <header>
          HI,
        </header>
        <div>
          {user ? <SignOutButton /> : <SignInButton />}

          {user ? 
          <>
           <AddPuzzleButton
           user={user}
           addedPuzzleFlag={addedPuzzleFlag}
           setAddedPuzzleFlag={setAddedPuzzleFlag} />
          <PuzzlesBoard
          user={user}
          addedPuzzleFlag={addedPuzzleFlag}
          setAddedPuzzleFlag={setAddedPuzzleFlag} /> 
          </>
          : null }


        </div>
    </div>
  );
}

function SignInButton() {
  const SignIn = () => {
    const provider = new GoogleAuthProvider();
    signInWithPopup(auth, provider)
    .then(async (result) => {
      let user = result.user
      const userRef = doc(db, 'users', user.uid);
      const userSnap = await getDoc(userRef);
      if(!userSnap.exists()) {
        console.log(user);
        await setDoc(doc(db, 'users', user.uid), {
          email: user.email,
          name: user.displayName,
          puzzles: []
        });
      }
    });
  }

  return (
    <button onClick={SignIn}>Sign In</button>
  )
}

function SignOutButton() {
  const SignOut = () => {
    signOut(auth);
  }
  return auth.currentUser && (
    <button onClick={SignOut}>Sign Out</button>
  )
}

function AddPuzzleButton(props) {

  const [formPuzzleTitle, setFormPuzzleTitle] = useState('');
  const AddPuzzle = async (e) => {
    e.preventDefault();
    const userRef = doc(db, 'users', props.user.uid);
    await updateDoc(userRef, {
      puzzles:  arrayUnion(formPuzzleTitle)
    })

    setFormPuzzleTitle('');
    props.setAddedPuzzleFlag(props.addedPuzzleFlag+1);
  }

  return (
    <form onSubmit={AddPuzzle}>
      <input value={formPuzzleTitle} onChange={(e) => setFormPuzzleTitle(e.target.value)} placeholder='Puzzle Title'/>
      <button type='submit' disabled={!formPuzzleTitle}>Add Puzzle</button>
    </form>
  )
}

 function PuzzlesBoard(props) {

  const [puzzleList, setPuzzleList] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
        const userRef = doc(db, 'users', props.user.uid);
        const userSnap = await getDoc(userRef);
        setPuzzleList(userSnap.data().puzzles);
        console.log(userSnap.data().puzzles);
        console.log(puzzleList);
      }

  fetchData();
  },[props.addedPuzzleFlag]);

  return (
    <div>
      {puzzleList.map(puzzle => 
      <>
      <p>{puzzle}</p> <button>Delete</button>
      </>
      )}

    </div>
  );
}

export default App;
